48: function shouldInjectSensitivity(
49:   sensitivity: string,
50:   userMessage: string,
51:   queryMode: QueryMode,
52: ): boolean {
53:   if (queryMode === "recall") {
54:     return sensitivity !== "private";
55:   }
56:   if (sensitivity === "none") return true;
57:   if (sensitivity === "private") return false;
58:   if (sensitivity === "pharma" || sensitivity === "health") {
