69: function buildRecallDelivery(
70:   queryMode: QueryMode,
71:   storeIsEmpty: boolean,
72:   repeatRecall: boolean,
73: ): string | null {
74:   if (queryMode === "soft_recall") {
75:     return "Doc is asking about something you two already talked about. Answer him normally, from what is above and from this thread. If it is not there, say that plainly instead of reconstructing something plausible.";
76:   }
77:   if (queryMode !== "recall") return null;
