79:   const lines = [
80:     "Doc is asking what you have stored. Two sentences at most, no lists, no roleplay, no persona tour.",
81:     storeIsEmpty
82:       ? "Nothing is stored long term. Say so plainly and word it differently than last time."
83:       : "You may name what is stored, briefly, and nothing beyond it.",
84:     "At most one topic from recent messages, as a short phrase rather than a list.",
85:   ];
86:   if (repeatRecall) {
87:     lines.push(
88:       "You already answered this in this thread. Same honest meaning, different words.",
89:     );
90:   }
91:   return lines.join("\n");
