135:   const parts: string[] = ["What you actually have on Doc:", "", "## Standing facts"];
136:   if (factLines.length > 0) parts.push(...factLines);
137: 
138:   parts.push("", "## Where things left off");
139:   if (narrativeParts.length > 0) parts.push(narrativeParts.join(" "));
140: 
141:   parts.push("", "## May be relevant now");
142:   if (snippets.length > 0 && queryMode === "normal") {
