156:     "",
157:     "Trust order: standing facts, reflection notes, then where things left off, then this thread's messages. Echoes are hints, never facts. A blank section means you have nothing there, not that you should reconstruct it.",
158:   );
159: 
160:   const storeIsEmpty = factLines.length === 0 && narrativeParts.length === 0;
161:   const recallDelivery = buildRecallDelivery(
