135: function sameStance(a: string, b: string): boolean {
136:   const norm = (s: string) => s.toLowerCase().replace(/[^\p{L}\p{N} ]/gu, "").trim();
137:   if (norm(a) === norm(b)) return true;
138:   const ta = new Set(tokens(a));
139:   const tb = tokens(b);
140:   if (ta.size === 0 || tb.length === 0) return false;
141:   const shared = tb.filter((w) => ta.has(w)).length;
142:   return shared / Math.max(ta.size, tb.length) >= 0.7;
143: }
