158: /** Cheap lexical overlap; a stance only shows up when the topic is live. */
159: export function selectRelevantStances(
160:   stances: Stance[],
161:   message: string,
162:   max = 3,
163: ): Stance[] {
164:   const words = new Set(tokens(message));
165:   if (words.size === 0) return [];
166: 
167:   const scored = stances
168:     .map((s) => {
169:       const hay = tokens(`${s.topic} ${s.stance}`);
170:       const hits = hay.filter((w) => words.has(w)).length;
171:       return { s, score: hits };
172:     })
173:     .filter((r) => r.score > 0)
174:     .sort(
175:       (a, b) =>
176:         b.score - a.score ||
177:         b.s.times_reinforced - a.s.times_reinforced ||
178:         b.s.confidence - a.s.confidence,
179:     );
180: 
181:   return scored.slice(0, max).map((r) => r.s);
182: }
