        buildChatMessages({
          system: appendMemoryBlock(promptParts, assembled.memoryBlock, {
            presence: presenceNote,
            capability: capabilityNote,
            curiosity: withCuriosity?.text,
            sharp: sharpNote,
            voice: buildVoiceBlock(withExamples),
            guard,
